typeChecks.mutated:
type Notice = ({
    kind: "waiting";
} | {
    kind: "ready";
    title: string;
} | {
    kind: "failed";
    reason: string;
}) | {
    kind: "paused";
};
function assertNever(value: never): never { throw new Error("Unhandled notice"); }
function noticeText(notice: Notice): string {
    switch (notice.kind) {
        case "waiting": return "Waiting";
        case "ready": return "Ready: " + notice.title;
        case "failed": return "Failed: " + notice.reason;
        default: return assertNever(notice);
    }
}
